        rows = Membership.objects.filter(
            member_id=group["member_id"],
            org_unit_id=group["org_unit_id"],
            role_id=group["role_id"],
            end_date__isnull=True,
        ).order_by("-is_primary", "id")
        keep = rows.first()
        rows.exclude(pk=keep.pk).delete()


